import {INSURERS,REFERENCE_DATE} from './data.js';
export const daysUntil=(date)=>Math.round((new Date(date+'T12:00:00Z')-new Date(REFERENCE_DATE+'T12:00:00Z'))/86400000);
export function requestDocuments(s,c,p){return s.documents.filter(d=>d.clientId===c.clientId&&(d.policyId===p.id||(!d.policyId&&d.title==='Ficha del vehículo')));}
export const demoTimestamp=()=>REFERENCE_DATE+'T'+new Intl.DateTimeFormat('en-GB',{timeZone:'America/Bogota',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())+'-05:00';
export function event(s,caseId,title,detail,clientId){s.events.unshift({id:uid('ev'),caseId,clientId:clientId||s.cases.find(c=>c.id===caseId)?.clientId,at:demoTimestamp(),title,detail,actor:'Sesión demo'});}
export const uid=(prefix)=>`${prefix}-${globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)}`;
export function validateIntake(s,id,end){const item=s.intake.find(x=>x.id===id);if(!item)throw Error('Expediente no encontrado.');if(item.status==='done')return false;const p=s.policies.find(x=>x.id===item.policyId);if(item.kind==='conflict'){if(end!==p.end)throw Error('La fecha no coincide con la carátula de muestra. Revisa el documento fuente: 5 de noviembre de 2026.');p.validated=true;}if(item.kind==='missing'){s.documents.push({id:'soporte-sede',clientId:p.clientId,policyId:p.id,title:'Ficha de riesgos · sede de muestra',type:'Soporte de muestra',source:'Incorporación simulada',date:REFERENCE_DATE,file:`documentos/soporte-${p.clientId}.html`,status:'Disponible'});p.validated=true;}item.status='done';const d=s.documents.find(x=>x.id===p.docId);if(d)d.status='Revisado';const c=s.cases.find(x=>x.policyId===p.id);if(c&&item.kind==='conflict')c.next='Preparar solicitud de cotización';event(s,c?.id,'Información revisada',item.kind==='duplicate'?'Duplicado descartado. Se conservó la póliza existente.':`Validación de ${p.number} con documento de muestra.`,p.clientId);return true;}
export function prepareRequests(s,caseId,insurerIds){const c=s.cases.find(x=>x.id===caseId),p=s.policies.find(x=>x.id===c?.policyId);if(!p)throw Error('Selecciona un caso con póliza.');if(p.cancelledAt||p.status==='Cancelada')throw Error('La vigencia está cancelada. Conserva su historial y registra otro caso.');if(p.product!=='Automóvil')throw Error('El adaptador de cotización del demo está preparado para automóvil. Los demás productos conservan su expediente y seguimiento.');if(!p.validated)throw Error('Confirma primero la vigencia en Incorporar documentos.');if(!insurerIds.length)throw Error('Selecciona al menos una aseguradora.');let added=0;for(const id of insurerIds){if(!INSURERS.some(x=>x.id===id))throw Error('Aseguradora simulada desconocida.');if(s.requests.some(r=>r.caseId===caseId&&r.insurerId===id))continue;s.requests.push({id:uid('req'),caseId,clientId:c.clientId,insurerId:id,status:'prepared',attempt:1,at:demoTimestamp(),attachments:requestDocuments(s,c,p).map(d=>d.id),payload:{clientId:c.clientId,policyId:p.id,risk:p.risk,sum:p.sum,start:p.end,period:'Anual'},quote:null});added++;}if(added){c.stage='solicitada';c.next='Simular respuestas de aseguradoras';event(s,caseId,'Solicitudes preparadas',`${added} solicitudes distintas con datos reutilizados. No hubo envíos externos.`);}return added;}
function quote(id){const i=INSURERS.find(x=>x.id===id);return {premium:i.premium,taxIncluded:true,period:'Anual',deductible:i.deductible,liability:i.liability,assistance:i.assistance,exclusions:i.exclusions,cover:i.limit,validUntil:'2026-10-31',source:`Propuesta ${i.short} · simulada`};}
export function simulateResponses(s,caseId){const reqs=s.requests.filter(r=>r.caseId===caseId);if(!reqs.length)throw Error('Prepara las solicitudes antes de simular respuestas.');let changed=0;for(const r of reqs){if(r.status!=='prepared')continue;r.status=r.insurerId==='a'?'quoted':r.insurerId==='b'?'missing':'waiting';if(r.status==='quoted')r.quote=quote(r.insurerId);s.messages.unshift({id:uid('m'),caseId,clientId:r.clientId,direction:'Saliente',channel:INSURERS.find(i=>i.id===r.insurerId).channel,recipient:`Aseguradora ${r.insurerId.toUpperCase()} · simulada`,subject:'Solicitud de cotización · renovación de automóvil',body:`Solicitud ${r.id}. Identificación ficticia ${s.clients.find(x=>x.id===r.clientId).identity}. ${r.payload.risk}. Valor de referencia ${r.payload.sum} COP. Vigencia solicitada desde ${r.payload.start}. Adjuntos de muestra: ${r.attachments.length}.\nNo se transmitió información.`,status:'Envío simulado',at:demoTimestamp()});if(r.status!=='waiting')s.messages.unshift({id:uid('m'),caseId,clientId:r.clientId,direction:'Entrante',channel:'Correo',recipient:'Agencia demo',subject:r.status==='missing'?'Información adicional requerida · B':'Propuesta de muestra recibida · A',body:r.status==='missing'?'Falta soporte del uso particular del vehículo. Este requisito es ficticio, no representa a una aseguradora real.':'Se adjunta propuesta ficticia con prima anual y condiciones de ejemplo. No constituye una oferta.',status:'Respuesta simulada',at:demoTimestamp()});changed++;}if(changed){const c=s.cases.find(x=>x.id===caseId);c.stage='comparacion';c.next='Resolver faltantes y comparar opciones';event(s,caseId,'Respuestas simuladas',`${changed} solicitudes procesadas. Los estados dependen del adaptador ficticio.`);}return changed;}
export function resolveRequest(s,requestId){const r=s.requests.find(x=>x.id===requestId);if(!r)throw Error('Solicitud no encontrada.');if(r.status!=='missing')return false;r.status='quoted';r.quote=quote(r.insurerId);const c=s.cases.find(x=>x.id===r.caseId);c.missingResolved=true;const docId=uid('support');s.documents.push({id:docId,clientId:c.clientId,policyId:c.policyId,title:'Declaración adicional de uso particular',type:'Soporte adicional ficticio',source:'Aporte simulado del cliente',date:REFERENCE_DATE,status:'Disponible',generated:true});r.attachments.push(docId);event(s,r.caseId,'Faltante resuelto · simulación','Se aportó soporte ficticio de uso particular. B devolvió una propuesta; no hubo envío externo.');s.messages.unshift({id:uid('m'),caseId:r.caseId,clientId:r.clientId,direction:'Entrante',channel:'Portal simulado',recipient:'Agencia demo',subject:'Propuesta de muestra recibida · B',body:'Soporte recibido en el escenario ficticio. Condiciones y prima anual disponibles en la comparación.',status:'Respuesta simulada',at:demoTimestamp()});return true;}
export function chooseQuote(s,caseId,requestId){const r=s.requests.find(x=>x.id===requestId&&x.caseId===caseId);if(!r?.quote)throw Error('Esta solicitud todavía no tiene propuesta.');if(s.policies.find(p=>p.id===s.cases.find(c=>c.id===caseId)?.policyId)?.cancelledAt)throw Error('La vigencia está cancelada.');const c=s.cases.find(x=>x.id===caseId);if(['emision','cerrada'].includes(c.stage))throw Error('La decisión del caso ya fue registrada. Conserva esta comparación como historial.');c.selected=requestId;event(s,caseId,'Opción para presentar',`${INSURERS.find(i=>i.id===r.insurerId).name} seleccionada para preparar el borrador. No es aceptación del seguro.`);}
export function customerDraft(s,caseId){const c=s.cases.find(x=>x.id===caseId),cl=s.clients.find(x=>x.id===c?.clientId),r=s.requests.find(x=>x.id===c?.selected);if(!r?.quote)throw Error('Selecciona una propuesta para preparar el mensaje.');const i=INSURERS.find(x=>x.id===r.insurerId),q=r.quote;return `Hola, ${cl.name.split(' ')[0]}:\n\nRevisamos las opciones para la renovación de tu automóvil. Te comparto la propuesta de ${i.name} (simulada):\n\n• Prima anual: ${new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(q.premium)}, impuestos incluidos en este ejemplo.\n• Deducible: ${q.deductible}.\n• Límite de responsabilidad civil: ${new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(q.liability)}.\n• Asistencias: ${q.assistance}.\n• Exclusiones del ejemplo: ${q.exclusions}.\n\nAntes de decidir, revisemos las condiciones y cualquier información pendiente. La propuesta de muestra vence el 31 de octubre de 2026.\n\nEste mensaje es ficticio y no constituye una oferta ni una confirmación de cobertura.`;}
export function sendDraft(s,caseId,body,template='propuesta'){if(!body.trim())throw Error('El mensaje está vacío.');const c=s.cases.find(x=>x.id===caseId);if(template==='propuesta'&&s.policies.find(p=>p.id===c.policyId)?.cancelledAt)throw Error('La vigencia está cancelada.');if(template==='propuesta'&&['emision','cerrada'].includes(c.stage))throw Error('Este caso ya tiene una decisión registrada. Usa otra plantilla para el seguimiento.');if(template==='propuesta'&&!c.selected)throw Error('Selecciona primero una propuesta.');s.messages.unshift({id:uid('m'),caseId,clientId:c.clientId,direction:'Saliente',channel:'Correo',recipient:template==='seguimiento'?'cotizaciones@aseguradora-demo.example.com':s.clients.find(x=>x.id===c.clientId).email,subject:template==='propuesta'?'Opciones para tu renovación':template==='seguimiento'?'Seguimiento a aseguradora':template==='faltantes'?'Documentos para continuar':'Revisión de tu renovación',body,status:'Envío simulado',at:demoTimestamp()});if(template==='propuesta'){c.stage='presentada';c.next='Esperar decisión del cliente';}delete s.drafts[caseId+':'+template];delete s.drafts[caseId];event(s,caseId,'Comunicación registrada',`Borrador ${template} marcado como enviado en el demo. No salió del navegador.`);}
export function addLead(s,{name,email,product,source,need}){if(!name?.trim()||!email?.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)||!product)throw Error('Completa nombre, correo de muestra y producto.');if(!email.toLowerCase().endsWith('@example.com'))throw Error('Usa un correo ficticio terminado en @example.com.');if(s.leads.some(l=>l.email===email&&l.product===product))throw Error('Ya existe una solicitud de ese correo y producto. Revisa Oportunidades.');const lead={id:uid('lead'),name:name.trim(),email,product,source,need:need?.trim()||'',status:'Por contactar',at:demoTimestamp()};s.leads.unshift(lead);event(s,null,'Lead ficticio recibido',`${lead.name} · ${product} · ${source}`);return lead;}
export function convertLead(s,id){const l=s.leads.find(x=>x.id===id);if(!l)throw Error('Solicitud no encontrada.');if(l.caseId)return l.caseId;let cl=s.clients.find(x=>x.email===l.email);if(!cl){cl={id:uid('c'),name:l.name,initials:l.name.split(' ').slice(0,2).map(w=>w[0]).join(''),type:'Persona',identity:`DEMO-LEAD-${s.leads.length}`,email:l.email,city:'Por confirmar',channel:'Correo',since:'2026',note:l.need};s.clients.push(cl);}const c={id:uid('r'),clientId:cl.id,policyId:null,type:'Negocio nuevo',title:`Asesoría de ${l.product.toLowerCase()}`,product:l.product,stage:'preparacion',next:'Contactar y validar necesidad',due:REFERENCE_DATE,source:l.source,selected:null};s.cases.push(c);l.caseId=c.id;l.status='En seguimiento';event(s,c.id,'Oportunidad abierta',`Origen: ${l.source}. Datos reutilizados desde el formulario.`,cl.id);return c.id;}
export function noteCase(s,id,text){if(!text.trim())throw Error('Escribe la gestión para guardarla.');event(s,id,'Gestión registrada',text.trim());}
